import { useEffect, useState } from 'react';
import { searchData } from '../services/tsApi';
import { THOUGHTSPOT_MODEL_ID } from '../config/thoughtspot';

export interface KpiValues {
  flightSpend: string;
  totalTrips: string;
  onPolicy: string;
  avgTripCost: string;
  carbonEmissions: string;
  activeTravellers: string;
  loading: boolean;
  error: boolean;
}

// Adjust these query strings to match your model's column names
const QUERIES = {
  flightSpend: '[total spend]',
  totalTrips: '[number of trips]',
  onPolicy: '[on policy] %',
  avgTripCost: '[average trip cost]',
  carbonEmissions: '[total carbon emissions]',
  activeTravellers: '[unique travellers]',
};

function formatNumber(val: any, isCurrency = false, isPercent = false): string {
  const n = parseFloat(String(val));
  if (isNaN(n)) return '—';
  if (isPercent) return `${Math.round(n)}%`;
  if (isCurrency) {
    if (n >= 1_000_000) return `$${(n / 1_000_000).toFixed(1)}M`;
    if (n >= 1_000) return `$${Math.round(n / 1000).toLocaleString()}K`;
    return `$${Math.round(n).toLocaleString()}`;
  }
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
  if (n >= 1_000) return `${Math.round(n / 1000).toLocaleString()}K`;
  return Math.round(n).toLocaleString();
}

async function fetchOne(query: string): Promise<any> {
  const result = await searchData(THOUGHTSPOT_MODEL_ID, query);
  return result.rows?.[0]?.[0] ?? null;
}

export function useKpiData(): KpiValues {
  const [values, setValues] = useState<KpiValues>({
    flightSpend: '—',
    totalTrips: '—',
    onPolicy: '—',
    avgTripCost: '—',
    carbonEmissions: '—',
    activeTravellers: '—',
    loading: true,
    error: false,
  });

  useEffect(() => {
    let cancelled = false;

    (async () => {
      try {
        const [flightSpend, totalTrips, onPolicy, avgTripCost, carbonEmissions, activeTravellers] =
          await Promise.allSettled([
            fetchOne(QUERIES.flightSpend),
            fetchOne(QUERIES.totalTrips),
            fetchOne(QUERIES.onPolicy),
            fetchOne(QUERIES.avgTripCost),
            fetchOne(QUERIES.carbonEmissions),
            fetchOne(QUERIES.activeTravellers),
          ]);

        if (cancelled) return;

        const get = (r: PromiseSettledResult<any>) =>
          r.status === 'fulfilled' ? r.value : null;

        setValues({
          flightSpend: formatNumber(get(flightSpend), true),
          totalTrips: formatNumber(get(totalTrips)),
          onPolicy: formatNumber(get(onPolicy), false, true),
          avgTripCost: formatNumber(get(avgTripCost), true),
          carbonEmissions: get(carbonEmissions) != null
            ? `${formatNumber(get(carbonEmissions))} KG`
            : '—',
          activeTravellers: formatNumber(get(activeTravellers)),
          loading: false,
          error: false,
        });
      } catch {
        if (!cancelled) setValues(v => ({ ...v, loading: false, error: true }));
      }
    })();

    return () => { cancelled = true; };
  }, []);

  return values;
}
